import{_ as e,o as s,c as n,a4 as t}from"./chunks/framework.BRzJ4ijD.js";const u=JSON.parse('{"title":"第七部分 · 系统设计","description":"","frontmatter":{},"headers":[],"relativePath":"system-design/index.md","filePath":"system-design/README.md","lastUpdated":1788475713000}'),l={name:"system-design/index.md"};function i(r,a,o,p,c,d){return s(),n("div",null,[...a[0]||(a[0]=[t(`<h1 id="第七部分-·-系统设计" tabindex="-1">第七部分 · 系统设计 <a class="header-anchor" href="#第七部分-·-系统设计" aria-label="Permalink to &quot;第七部分 · 系统设计&quot;">​</a></h1><h2 id="一句话" tabindex="-1">一句话 <a class="header-anchor" href="#一句话" aria-label="Permalink to &quot;一句话&quot;">​</a></h2><p>系统设计 = 把&quot;业务需求 + 流量规模 + 可用性目标 + 预算&quot;翻译成<strong>架构图 + API contracts + 存储 + 队列 + 缓存 + 监控的具体取舍</strong>。 不是堆 slogan, 而是在<strong>真实分布式 SLA、capex 预算、ops 复杂度</strong>中给一个<strong>可以跑 10 年不重写</strong>的设计——并解释每个组件的选择与淘汰路径。</p><h2 id="思想链" tabindex="-1">思想链 <a class="header-anchor" href="#思想链" aria-label="Permalink to &quot;思想链&quot;">​</a></h2><p>API 高层: 用户 / API 客户端 —— LB / CDN —— API gateway —— 业务服务群 (stateless) —— 缓存 Redis/Memcached —— 主库 (强一致 KV / RDBMS) —— OLAP 副本 / 数仓 —— 备份 / 异地灾备</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Client</span></span>
<span class="line"><span>  ↓ HTTP / gRPC</span></span>
<span class="line"><span>[ Edge CDN (Fastly / Cloudflare / Akamai) ]</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>[ LB (L4 NLB / L7 ALB) ]</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>[ API Gateway (Kong / Envoy / Nginx / internal OAuth + rate limit) ]</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>[ Stateless Microservices (K8s deployment) ]</span></span>
<span class="line"><span>  ├─ Redis cluster (cache + distributed locks)</span></span>
<span class="line"><span>  ├─ Kafka/Pulsar (异步事件流)</span></span>
<span class="line"><span>  ├─ Primary DB (PostgreSQL / MySQL / Spanner / CockroachDB)</span></span>
<span class="line"><span>  ├─ OLAP store (Snowflake / BigQuery / ClickHouse / Doris)</span></span>
<span class="line"><span>  └─ Object storage (S3 / GCS / OSS)</span></span></code></pre></div><p>每一跳都有取舍——CDN 让主页快 10× 但增加 invalidation 复杂度; cache 让 read 5ms 但 stale risk 提高; message queue 让 service 解耦 但 at-least-once 必须 idempotent; 主备 DB 让事务强一致但 leader failover 5-10s 写阻塞。 真正的设计师在<strong>这套取舍的尖点中</strong>画最优弧线。</p><h2 id="_8-个章节" tabindex="-1">8 个章节 <a class="header-anchor" href="#_8-个章节" aria-label="Permalink to &quot;8 个章节&quot;">​</a></h2><ul><li><a href="./estimation/">负载与容量估算</a> — back-of-envelope、Little&#39;s Law、负载模式</li><li><a href="./storage/">存储选型与内部</a> — 选什么数据库 (KV / 关系 / 列存 / 文档 / 时序) + WAL/LSM/B-tree 内部</li><li><a href="./cache/">缓存</a> — 多级 cache、常见 pattern、failure modes (缓存雪崩、缓存穿透、缓存击穿)</li><li><a href="./queue/">消息队列与异步</a> — Kafka/Pulsar/SQS + Outbox pattern + semantics (at-most/at-least/exactly-once)</li><li><a href="./monitor/">可观测性</a> — Three pillars (metrics/logs/traces)、SLO/SLI、监控 stack</li><li><a href="./scale/">扩展与可用性</a> — sharding + replication + multi-region + resilience</li><li><a href="./case/">经典系统案例</a> — Google Bigtable/Spanner/Chubby + Dynamo family + Snowflake + K8s control plane</li></ul><p>读完应能回答:</p><ol><li>100K QPS 电商秒杀: back-of-envelope 快速决定热点 key cache + 静态化页 + 异步下单 + 限流降级</li><li>PostgreSQL vs DynamoDB vs ClickHouse 选型的真实 SLA 矩阵</li><li>Cache hit ratio / 命中率 / evict policy / dogpile effect 在 P99 latency 上贡献</li><li>Kafka vs Pulsar 的语义差异与重复消费 idempotent 设计</li><li>multi-region 容灾或 AP 数据库分别在不同业务 SLA 下的选择</li><li>SLO 三要件: SLI 定义、error budget、automation burn rate alerts</li></ol><hr><p>下一节 → <a href="./estimation/">负载与容量估算</a></p>`,13)])])}const m=e(l,[["render",i]]);export{u as __pageData,m as default};
